response.body:
{
  "responseId": "{{randomValue length=36 type='ALPHANUMERIC'}}",
  "paymentId": "{{jsonPath '$.paymentId'}}",
  "status": "SUCCESS",
  "statusCode": "ACSC",
  "statusDescription": "PayShap payment successfully processed",
  "processingTime": "{{now format='yyyy-MM-dd\'T\'HH:mm:ss.SSS\'Z\''}}",
  "settlementTime": "{{now format='yyyy-MM-dd\'T\'HH:mm:ss.SSS\'Z\''}}",
  "reference": "{{jsonPath '$.reference'}}",
  "amount": {
    "value": "{{jsonPath '$.amount.value'}}",
    "currency": "{{jsonPath '$.amount.currency'}}"
  },
  "fees": {
    "value": "2.50",
    "currency": "ZAR"
  },
  "clearingSystem": {
    "name": "PayShap",
    "operator": "BankservAfrica",
    "version": "2.0",
    "serviceType": "P2P"
  },
  "participants": {
    "originator": {
      "bankCode": "{{jsonPath '$.originator.bankCode'}}",
      "accountNumber": "{{jsonPath '$.originator.accountNumber'}}",
      "mobileNumber": "{{jsonPath '$.originator.mobileNumber'}}"
    },
    "beneficiary": {
      "bankCode": "{{jsonPath '$.beneficiary.bankCode'}}",
      "accountNumber": "{{jsonPath '$.beneficiary.accountNumber'}}",
      "mobileNumber": "{{jsonPath '$.beneficiary.mobileNumber'}}"
    }
  },
  "payShapDetails": {
    "transactionType": "P2P",
    "instantSettlement": true,
    "qrCode": "{{randomValue length=50 type='ALPHANUMERIC'}}",
    "deepLink": "payshap://payment/{{jsonPath '$.paymentId'}}"
  },
  "metadata": {
    "clearingSessionId": "{{randomValue length=20 type='ALPHANUMERIC'}}",
    "processingBatch": "{{now format='yyyyMMdd'}}",
    "sequenceNumber": "{{randomValue length=6 type='NUMERIC'}}",
    "apiVersion": "2.0"
  }
}
